programs.code:
move("east", 1);
pickup("moss-fruit");
learn({"name":"Eat safe fruit","purpose":"Restore satiety by eating an owned edible fruit.","target":"A fruit resource in my inventory with positive nutrition and zero toxicity.","conditions":"Requires an owned fruit unit; consume one unit in one use, without tools or preparation.","expectedEffect":"Apply the consumed fruit's nutrition to my satiety up to the cap, applying its actual toxicity if any. Please provide the learned skill ID and exact argument names."});

move("east", 1);
pickup("sol-fruit");
learn({"name":"Eat safe fruit","purpose":"Restore satiety by consuming edible fruit from my inventory.","target":"An owned fruit resource identified by itemId.","conditions":"Learn in one round. Use only when the resource is in my inventory, has positive quantity and nutrition, and has zero toxicity. Consume one unit per use.","expectedEffect":"Apply the consumed unit's nutrition to my satiety up to 100, apply its actual toxicity, and reduce its quantity by one. Expose the capability with parameter itemId."});

use("skill-1", {"food":"moss-fruit"});
move("east", 1);
learn({"name":"Harvest tree fruit","purpose":"Obtain safe food from a nearby fruit-bearing tree for later consumption.","target":"The adjacent tree moss-tree, which has four fruit in its stock.","conditions":"Requires being cardinally adjacent to the tree and at least one fruit remaining in its stock. Harvest one fruit by hand without tools, depleting the tree's fruit stock by one and transferring the fruit into my inventory.","expectedEffect":"Gain one owned fruit resource with its actual nutrition and toxicity preserved, ready to consume with skill-1. Return the learned skill ID and exact parameter names."});

use("skill-1", {"food":"sol-fruit"});
move("east", 1);
learn({"name":"Harvest tree fruit","purpose":"Obtain safe edible fruit from a nearby tree for ongoing nourishment.","target":"An adjacent standing tree identified by objectId with positive fruit stock.","conditions":"Learn in one round if possible. Require cardinal adjacency to the tree and at least one fruit in its stock. Harvest only fruit, without consuming it or damaging the tree.","expectedEffect":"Reduce the target tree's fruit stock by one and transfer one fruit unit into my inventory with its actual nutrition and toxicity preserved. Return the owned resource ID for later consumption."});
